import React, { useEffect, useState } from 'react';

function App() {
  const [scores, setScores] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 1. 처음 페이지 열릴 때 한 번 가져오기
    fetchScores();

    // 2. 3초(3000ms)마다 서버에 새 점수가 있는지 계속 물어보기 (이게 핵심!)
    const interval = setInterval(() => {
      fetchScores();
    }, 3000); 

    // 3. 페이지 나갈 때 타이머 청소
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ padding: 24 }}>
      <h1>점수판</h1>
      {loading ? (
        <p>로딩 중...</p>
      ) : (
        <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', minWidth: 320 }}>
          <thead>
            <tr>
              {scores.length > 0 ? (
                Object.keys(scores[0]).map((key) => (
                  <th key={key}>{key}</th>
                ))
              ) : (
                <th>점수 데이터 없음</th>
              )}
            </tr>
          </thead>
          <tbody>
            {scores.length === 0 ? (
              <tr>
                <td colSpan="100%">점수가 없습니다.</td>
              </tr>
            ) : (
              scores.map((score, idx) => (
                <tr key={idx}>
                  {Object.values(score).map((val, i) => (
                    <td key={i}>{val}</td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default App;
